<?php
function consultationDetails(array $p):array{
 $date=required($p,'booking_date');attRequire(dateValid($date),'Use a valid booking date.');$manual=($p['booking_mode']??'timetable')==='manual';
 if($manual){$faculty=(int)($p['faculty_id']??0);$u=one("SELECT * FROM users WHERE id=? AND active=1 AND role IN ('faculty','hod','pl','daa')",[$faculty]);attRequire((bool)$u,'Select an active tutor.');q('UPDATE users SET active=active WHERE id=?',[$faculty]);attRequire(!one('SELECT id FROM slots WHERE faculty_id=? AND active=1',[$faculty]),'This tutor has a published timetable. Select a timetable slot instead.');$start=required($p,'manual_start');$end=required($p,'manual_end');attRequire(timeValid($start)&&timeValid($end)&&$end>$start,'Check your requested start and end time.');$location='To be confirmed by tutor';$slot=null;
 }else{$slot=one('SELECT s.* FROM slots s JOIN users u ON u.id=s.faculty_id WHERE s.id=? AND s.active=1 AND u.active=1',[(int)($p['slot_id']??0)]);attRequire((bool)$slot,'Select a valid consultation slot.');$faculty=(int)$slot['faculty_id'];q('UPDATE users SET active=active WHERE id=?',[$faculty]);$slot=one('SELECT * FROM slots WHERE id=? AND active=1',[$slot['id']]);attRequire($slot&&(int)date('N',strtotime($date))===(int)$slot['weekday'],'Appointment date must match the timetable weekday.');$start=$slot['start_time'];$end=$slot['end_time'];$location=$slot['location'];}
 attRequire($date.' '.$start>date('Y-m-d H:i'),'Choose a future appointment.');
 attRequire(!one("SELECT a.request_id FROM consultation_appointments a JOIN requests r ON r.id=a.request_id WHERE a.faculty_id=? AND a.day=? AND a.start_time<? AND a.end_time>? AND r.status <> 'Cancelled'",[$faculty,$date,$end,$start]),'This tutor already has an overlapping consultation. Choose another time.');
 foreach(scheduledRows()as $teachingSlot)if((int)$teachingSlot['staff_id']===$faculty&&occurs($teachingSlot,$date)&&$teachingSlot['start_time']<$end&&$teachingSlot['end_time']>$start)throw new RuntimeException('The requested time overlaps this tutor’s teaching timetable. Choose another time.');
 return ['faculty'=>$faculty,'slot'=>$slot['id']??null,'start'=>$start,'end'=>$end,'location'=>$location,'mode'=>$manual?'Manual request':'Published timetable'];
}
function consultationPreview(array $rows):array{
 $headers=array_map(fn($v)=>trim(ltrim((string)$v,"\xEF\xBB\xBF")),array_shift($rows)??[]);foreach(['Tutor Email','Day','Start Time','End Time','Location']as $h)attRequire(in_array($h,$headers,true),'Missing column: '.$h);attRequire(count($headers)===count(array_unique($headers)),'Duplicate headers.');$out=[];$slots=all('SELECT * FROM slots WHERE active=1');foreach($rows as $i=>$row){if(!array_filter($row))continue;$r=array_combine($headers,array_slice(array_pad($row,count($headers),''),0,count($headers)));$u=one("SELECT * FROM users WHERE LOWER(email)=? AND active=1 AND role IN ('faculty','hod','pl','daa')",[strtolower(trim($r['Tutor Email']))]);attRequire((bool)$u,'Row '.($i+2).': tutor email not found in staff directory.');$s=['faculty_id'=>$u['id'],'weekday'=>dayNumber($r['Day']),'start_time'=>$r['Start Time'],'end_time'=>$r['End Time'],'location'=>trim($r['Location'])];attRequire($s['weekday']<=5&&timeValid($s['start_time'])&&timeValid($s['end_time'])&&$s['end_time']>$s['start_time']&&$s['location']!==''&&mb_strlen($s['location'])<=160,'Row '.($i+2).': invalid weekday, time or location.');foreach($slots as $old)attRequire(!($old['faculty_id']==$s['faculty_id']&&$old['weekday']==$s['weekday']&&$old['start_time']<$s['end_time']&&$old['end_time']>$s['start_time']),'Row '.($i+2).': tutor slot overlaps existing timetable or another upload row.');$slots[]=$s;foreach(['Department','Term','Modules','Free Days','Kind']as $k)$s[$k]=$r[$k]??'';$out[]=$s;}attRequire((bool)$out,'No rows found.');return $out;
}
function consultationImport(array $items,array $u):int{attRequire(academic($u));foreach($items as $s){q('UPDATE users SET active=active WHERE id=?',[$s['faculty_id']]);attRequire((bool)one("SELECT id FROM users WHERE id=? AND active=1 AND role IN ('faculty','hod','pl','daa')",[$s['faculty_id']]),'Tutor is no longer available.');attRequire(!one('SELECT id FROM slots WHERE faculty_id=? AND weekday=? AND active=1 AND start_time<? AND end_time>?',[$s['faculty_id'],$s['weekday'],$s['end_time'],$s['start_time']]),'Timetable changed after preview. Upload again.');q('INSERT INTO slots(faculty_id,weekday,start_time,end_time,location) VALUES(?,?,?,?,?)',[$s['faculty_id'],$s['weekday'],$s['start_time'],$s['end_time'],$s['location']]);q('INSERT INTO consultation_slot_details(slot_id,department,term,modules,free_days,kind) VALUES(?,?,?,?,?,?)',[(int)db()->lastInsertId(),$s['Department']??'',$s['Term']??'',$s['Modules']??'',$s['Free Days']??'',$s['Kind']??'']);}return count($items);}
